def calculate_successful_shots(aim):
    """
    Calculates the number of successful shots based on the aim rating.
    Aim rating of 1 means perfect aim, while 0 means no aim.
    """
    return int(aim * 10)  # Assuming aim rating is out of 10

def mark_shot_ducks(ducks, successful_shots):
    """
    Marks the successful shots in the duck string with 'X'.
    """
    ducks_list = list(ducks)
    for i in range(successful_shots):
        if ducks_list[i] != 'X':
            ducks_list[i] = 'X'
    return ''.join(ducks_list)

